// AgentSession Minimal session summary as returned by GET /agents/{id}/sessions. Maps to the AgentSession interface in src/lib/api.ts. This is the same underlying session.UnifiedMeta object, but the SPA consumes it through the AgentSession interface which reads id, title, created_at, and updated_at directly.
type AgentSession struct {
	// CreatedAt RFC3339 creation timestamp.
	CreatedAt time.Time `json:"created_at"`

	// Id Session identifier.
	Id string `json:"id"`

	// Title Session title.
	Title string `json:"title"`

	// UpdatedAt RFC3339 last-update timestamp.
	UpdatedAt time.Time `json:"updated_at"`
}

// AgentShellPolicy Per-agent shell command deny-pattern configuration.
type AgentShellPolicy struct {
	// CustomDenyPatterns Additional Go regexp patterns to block in shell commands.
	CustomDenyPatterns *[]string `json:"custom_deny_patterns,omitempty"`

	// EnableDenyPatterns Enable pattern-based shell command blocking.
	EnableDenyPatterns *bool `json:"enable_deny_patterns,omitempty"`
}

// AgentStats Aggregate runtime statistics for an agent. Absent on the Agent object when no sessions have been run.
type AgentStats struct {
	// LastActive RFC3339 timestamp of the last turn completed by this agent.
	LastActive *time.Time `json:"last_active,omitempty"`

	// TotalCost Lifetime USD cost across all sessions.
	TotalCost float64 `json:"total_cost"`

	// TotalSessions Lifetime count of sessions created for this agent.
	TotalSessions int `json:"total_sessions"`

	// TotalTokens Lifetime token count across all sessions.
	TotalTokens int `json:"total_tokens"`
}

// AgentTokenEntry Per-agent token usage entry within a TokenUsageSummary.
type AgentTokenEntry struct {
	AgentId   string `json:"agent_id"`
	AgentName string `json:"agent_name"`

	// ByModel Per-model breakdown for this agent. Absent when no model data is available.
	ByModel *map[string]struct {
		// CacheRead Cache-read tokens (served from KV cache) for this model. A SUBSET of total, not additive to it.
		CacheRead *int `json:"cache_read,omitempty"`

		// CacheWrite Cache-write tokens (written into a new cache entry) for this model. A SUBSET of total, not additive to it.
		CacheWrite *int `json:"cache_write,omitempty"`

		// In Uncached input tokens for this model. On the assistant-turn write path this stays 0 (the full turn total is recorded directly in total); it is only populated via the UpdateStats delta path.
		In *int `json:"in,omitempty"`

		// Out Output-side tokens for this model. On the assistant-turn write path this stays 0 (per-model accounting records the authoritative total directly).
		Out *int `json:"out,omitempty"`

		// Total Authoritative total tokens recorded for this model. cache_read/cache_write are a subset of total, NOT additive — do not reconstruct total as in + out + cache_read + cache_write.
		Total int `json:"total"`
	} `json:"by_model,omitempty"`

	// TokensCacheRead Total cache-read tokens for this agent in the period.
	TokensCacheRead *int `json:"tokens_cache_read,omitempty"`

	// TokensCacheWrite Total cache-write tokens for this agent in the period.
	TokensCacheWrite *int `json:"tokens_cache_write,omitempty"`
	TokensIn         int  `json:"tokens_in"`
	TokensOut        int  `json:"tokens_out"`
	TokensTotal      int  `json:"tokens_total"`
}

// AgentToolEntry Per-tool entry returned by GET /api/v1/agents/{id}/tools (FR-086, MAJ-008). Exposes both the configured policy and the effective policy so the SPA can display policy downgrades, plus the manifest tier so the panel can show which tools are always-callable versus loaded on demand.
type AgentToolEntry struct {
	// ConfiguredPolicy The policy as written in the agent's config.
	ConfiguredPolicy AgentToolEntryConfiguredPolicy `json:"configured_policy"`

	// EffectivePolicy The policy actually enforced at LLM-call time after global policy overrides are applied.
	EffectivePolicy AgentToolEntryEffectivePolicy `json:"effective_policy"`

	// ManifestTier How the tool is presented to the LLM when the manifest optimization is active. "full" = always sent as a callable tool definition every turn; "compressed" = listed by name only in the system context, schema fetched on demand via load_tool; "infra" = always-callable discovery tool (load_tool / search_tools_*) that drives the manifest mechanism itself and never appears in the manifest block.
	ManifestTier AgentToolEntryManifestTier `json:"manifest_tier"`

	// Name Canonical tool name.
	Name string `json:"name"`
}

// AgentToolEntryConfiguredPolicy The policy as written in the agent's config.
type AgentToolEntryConfiguredPolicy string

