// ExecutorConfig Executor configuration for a sub-agent. Controls which runtime is used to execute the sub-agent's tasks.
// "native" (default) runs the task inside the Omnipus agent loop — the existing behaviour, always available.
// "external-cli" drives an external CLI tool (claude-code, codex, or opencode) as a subprocess. There is no `--prompt` flag on any of the three supported CLIs: claude receives the soul+instructions prompt via stdin with NO positional prompt argument at all (a bare "-" is read by this CLI as a literal one-character prompt string, not a stdin sentinel, so none is appended — claude -p consumes all of stdin automatically when no positional prompt is given); codex also receives it via stdin, but signals that with a trailing "-" positional argument (a real stdin sentinel for this CLI); opencode receives it as a POSITIONAL argument after a literal "--" end-of-options separator (never via stdin). `--model <model>` IS passed as a real flag when a model is configured (opencode additionally requires it to be shaped like "provider/model" or it is omitted). See GET /api/v1/agents/executor-defaults for the full, byte-accurate per-CLI flag list. The CLI's auth, isolation, and retries are managed by the CLI itself (not Omnipus), so fields like shell_policy / tools_cfg / fallback_models / model_params / skills are hidden for subagent_3p agents and rejected 400 on PUT if set.
// "cli" (required for subagent_3p agents when kind="external-cli") is locked after create — to switch CLIs, the user must create a new agent. Mutating attempts on PUT return 400 with "executor.cli is locked after create; create a new agent to switch CLIs."
// "remote-a2a" is RESERVED for future A2A protocol resolution. The schema accepts it for forward-compatibility, but dispatch rejects it in v0.1.0 with an error ("not available in v0.1.0").
// The "kind" field is derived server-side from the agent's type (Main -> native, Subagent -> native, subagent_3p -> external-cli). It is exposed in responses but is NOT a writable field on create/update — clients cannot choose kind directly. Server-side derive at the handler boundary per the agent-form spec.
// When the agent has no executor block, the default is "native".
type ExecutorConfig struct {
	// Cli The three external CLI executors Omnipus can drive for a subagent_3p worker (kind="external-cli"): "claude-code" (pkg/agent/runner/driver_claude.go), "codex" (driver_codex.go), and "opencode" (driver_opencode.go). Shared by ExecutorConfig.cli (the agent's configured executor), ExecutorDefaults.cli (GET /api/v1/agents/executor-defaults' per-CLI reference row), and CliValidateRequest.cli (POST /api/v1/system/cli-validate) so the three stay a single generated type instead of three independently-declared enums that can drift apart (see the earlier oapi-codegen collision this schema resolves: before extraction, the symbol clash across the three inline enums forced generated constant names like "ExecutorConfigCliClaudeCode" instead of a clean shared "ExternalCliToolClaudeCode"). Titled "ExternalCliTool" rather than the shorter "ExternalCli" because ExecutorConfig.kind's "external-cli" enum VALUE (a completely different field, the execution- runtime selector) already generates an unprefixed Go constant literally named `ExternalCli` (of type ExecutorConfigKind) — reusing that identifier here would collide at compile time.
	Cli *ExternalCliTool `json:"cli,omitempty"`

	// CliArgs Free-form additional CLI arguments appended to the spawn invocation. The spawn layer uses execve (no shell interpolation), so values are passed safely; warn (but do not reject) on shell-injection chars in the value.
	CliArgs *string `json:"cli_args,omitempty"`

	// CliPath Filesystem path to the CLI binary. Required for subagent_3p agents. Mutable on PUT (allows upgrading the CLI binary without re-creating the agent). When empty, the OS $PATH is used (fragile when multiple CLI versions are installed — recommend an absolute path).
	CliPath *string `json:"cli_path,omitempty"`

	// EnvOverrides Additional environment variables merged into the spawned CLI process's environment alongside Omnipus's own (OMNIPUS_AGENT_NAME, OMNIPUS_AGENT_TYPE, and the master-key env var are NOT overridable — user-supplied keys take precedence only for non-Omnipus vars).
	EnvOverrides *map[string]string `json:"env_overrides,omitempty"`

	// Kind Execution runtime selector. Derived from the agent's type: Main -> native, Subagent -> native, subagent_3p -> external-cli. Clients cannot set this directly on create/update; the server overrides any client-supplied value. "remote-a2a" is reserved for future A2A protocol resolution.
	Kind *ExecutorConfigKind `json:"kind,omitempty"`
}

// ExecutorConfigKind Execution runtime selector. Derived from the agent's type: Main -> native, Subagent -> native, subagent_3p -> external-cli. Clients cannot set this directly on create/update; the server overrides any client-supplied value. "remote-a2a" is reserved for future A2A protocol resolution.
type ExecutorConfigKind string

// ExecutorDefaults Static reference data describing the CLI arguments Omnipus's external-CLI driver automatically applies when spawning a subagent_3p worker on this CLI (kind="external-cli"), as returned by GET /api/v1/agents/executor-defaults. This is READ-ONLY, computed reference information — it does not reflect any particular agent's configuration and there is nothing to write back. It exists so the Agent Profile UI can show operators the REAL, auto-applied flags (not merely HTML placeholder ghost-text) before they add their own executor.cli_args. The values are sourced directly from each driver's buildArgs() (pkg/agent/runner/driver_claude.go, driver_codex.go, driver_opencode.go) and must be kept byte-accurate to that code — this is reference documentation for a running system, not a design aspiration.
type ExecutorDefaults struct {
	// AutoAppliedFlags Human-readable, ORDERED list of the CLI arguments the driver appends before any operator-supplied executor.cli_args. Entries that are only applied conditionally (a configured model, max-turns cap, or working directory) say so in parentheses; the bracketed placeholder (e.g. "<configured model>") is not literal argv text. Operator cli_args are appended AFTER this list, and a narrow denylist strips any override that would re-enable a permission/sandbox bypass or corrupt the driver's stream-JSON output parsing (see argsafety.go).
	AutoAppliedFlags []string `json:"auto_applied_flags"`

	// Cli The three external CLI executors Omnipus can drive for a subagent_3p worker (kind="external-cli"): "claude-code" (pkg/agent/runner/driver_claude.go), "codex" (driver_codex.go), and "opencode" (driver_opencode.go). Shared by ExecutorConfig.cli (the agent's configured executor), ExecutorDefaults.cli (GET /api/v1/agents/executor-defaults' per-CLI reference row), and CliValidateRequest.cli (POST /api/v1/system/cli-validate) so the three stay a single generated type instead of three independently-declared enums that can drift apart (see the earlier oapi-codegen collision this schema resolves: before extraction, the symbol clash across the three inline enums forced generated constant names like "ExecutorConfigCliClaudeCode" instead of a clean shared "ExternalCliToolClaudeCode"). Titled "ExternalCliTool" rather than the shorter "ExternalCli" because ExecutorConfig.kind's "external-cli" enum VALUE (a completely different field, the execution- runtime selector) already generates an unprefixed Go constant literally named `ExternalCli` (of type ExecutorConfigKind) — reusing that identifier here would collide at compile time.
	Cli ExternalCliTool `json:"cli"`

	// Notes Free-text clarification covering how the prompt itself is delivered to this CLI (stdin vs. a positional argument — NEVER a --prompt flag on any of the three supported CLIs) and any other non-obvious behavior not captured by the flag list above.
	Notes string `json:"notes"`
}

// ExecutorSmokeTestRequest Runs a trivial, real prompt through an external-CLI worker's real dispatch path (the same driver.Run() a genuine subagent_3p delegation uses) and returns the real response. Distinct from the zero-token POST /agents/{id}/runner/test (binary-present → version handshake → credential-file-presence only, never spends a token) — this spawns a real, authenticated subprocess and costs real model usage, so it is an explicit operator action, never automatic. Mirrors POST /agents/executor-preview and POST /system/cli-validate's body-driven shape so it works from the create wizard too, but is NOT fully agent-agnostic like those two: when agent_id names a real, saved agent, the run happens in THAT agent's own dedicated directory ($OMNIPUS_HOME/agents/{id}/, AgentConfig.Workspace — NOT the separate, multi-agent pkg/workspace.Workspace feature; see agent.ResolveAgentWorkspace's own doc comment) — matching exactly where a genuine delegation to this agent would run, so the test is representative of real behavior (project files, AGENTS.md/CLAUDE.md/opencode.json context the CLI would actually see). Omitting agent_id (the create-wizard case, before the agent has been saved) or naming an agent that doesn't resolve falls back to a disposable, ephemeral scratch directory instead — the response's used_agent_workspace field says which one happened.
type ExecutorSmokeTestRequest struct {
	// AgentId Optional id of an existing, saved agent whose own dedicated directory ($OMNIPUS_HOME/agents/{id}/ — a per-agent folder, not the separate pkg/workspace.Workspace feature) this test should run in. When it resolves to a real agent, the run uses that directory (never deleted afterward — only the ephemeral scratch-directory fallback is cleaned up). When omitted, empty, or naming an agent that no longer exists, falls back to a disposable ephemeral scratch directory instead.
	AgentId *string `json:"agent_id,omitempty"`

	// Cli The three external CLI executors Omnipus can drive for a subagent_3p worker (kind="external-cli"): "claude-code" (pkg/agent/runner/driver_claude.go), "codex" (driver_codex.go), and "opencode" (driver_opencode.go). Shared by ExecutorConfig.cli (the agent's configured executor), ExecutorDefaults.cli (GET /api/v1/agents/executor-defaults' per-CLI reference row), and CliValidateRequest.cli (POST /api/v1/system/cli-validate) so the three stay a single generated type instead of three independently-declared enums that can drift apart (see the earlier oapi-codegen collision this schema resolves: before extraction, the symbol clash across the three inline enums forced generated constant names like "ExecutorConfigCliClaudeCode" instead of a clean shared "ExternalCliToolClaudeCode"). Titled "ExternalCliTool" rather than the shorter "ExternalCli" because ExecutorConfig.kind's "external-cli" enum VALUE (a completely different field, the execution- runtime selector) already generates an unprefixed Go constant literally named `ExternalCli` (of type ExecutorConfigKind) — reusing that identifier here would collide at compile time.
	Cli ExternalCliTool `json:"cli"`

	// CliArgs Free-form additional CLI arguments, same tokenizer and safety filter as ExecutorConfig.cli_args.
	CliArgs *string `json:"cli_args,omitempty"`

	// CliPath Optional executor.cli_path override, same semantics as ExecutorCommandPreviewRequest.cli_path.
	CliPath *string `json:"cli_path,omitempty"`

	// Model Model slug/shape to run with, same semantics as ExecutorCommandPreviewRequest.model.
	Model *string `json:"model,omitempty"`
}

// ExecutorSmokeTestResponse The result of actually running a trivial test prompt through an external-CLI worker's real dispatch path. Always 200 (even for a failed run) — the outcome is carried in `ok`/`error`, not the HTTP status, matching POST /system/cli-validate's convention of using the body for domain-level failure rather than 4xx/5xx.
type ExecutorSmokeTestResponse struct {
	// DurationMs Wall-clock time the run actually took, in milliseconds.
	DurationMs int `json:"duration_ms"`

	// Error A human-readable reason the run did not succeed (process failed to start, authentication failed, timed out, exceeded the bounded turn cap, or the CLI itself reported an error). Present when ok is false.
	Error *string `json:"error,omitempty"`

	// Ok Whether the CLI produced a real response before the bounded timeout/turn cap was reached.
	Ok bool `json:"ok"`

	// ResponseText The CLI's actual final response text. Present when ok is true; absent (or empty) otherwise.
	ResponseText *string `json:"response_text,omitempty"`

	// UsedAgentWorkspace True when the request's agent_id resolved to a real, saved agent and the run happened in that agent's own dedicated directory ($OMNIPUS_HOME/agents/{id}/, AgentConfig.Workspace — a per-agent folder, NOT the separate, multi-agent pkg/workspace.Workspace feature — this field name refers only to the former) — the same place a genuine delegation to it would run. False means the run happened in a disposable ephemeral scratch directory instead (agent_id was omitted, blank, or didn't resolve to an existing agent — e.g. testing from the create wizard before the agent has been saved).
	UsedAgentWorkspace bool `json:"used_agent_workspace"`
}

// ExternalCliTool The three external CLI executors Omnipus can drive for a subagent_3p worker (kind="external-cli"): "claude-code" (pkg/agent/runner/driver_claude.go), "codex" (driver_codex.go), and "opencode" (driver_opencode.go). Shared by ExecutorConfig.cli (the agent's configured executor), ExecutorDefaults.cli (GET /api/v1/agents/executor-defaults' per-CLI reference row), and CliValidateRequest.cli (POST /api/v1/system/cli-validate) so the three stay a single generated type instead of three independently-declared enums that can drift apart (see the earlier oapi-codegen collision this schema resolves: before extraction, the symbol clash across the three inline enums forced generated constant names like "ExecutorConfigCliClaudeCode" instead of a clean shared "ExternalCliToolClaudeCode"). Titled "ExternalCliTool" rather than the shorter "ExternalCli" because ExecutorConfig.kind's "external-cli" enum VALUE (a completely different field, the execution- runtime selector) already generates an unprefixed Go constant literally named `ExternalCli` (of type ExecutorConfigKind) — reusing that identifier here would collide at compile time.
type ExternalCliTool string

// FallbackModel One entry in an agent's fallback model chain. Carries its own provider so the fallback can route through a different provider than the primary (FR-007 / Phase 1B).
// Wire format: `{ "model": "<model-slug>", "provider": "<provider-key>" }`.
// Order matters — entries are tried in the order they appear in the parent's `fallback_models` array.
// `additionalProperties: false` — the wire type has exactly two fields; unknown keys are rejected (rendered as Zod strict mode). This prevents legacy `[string]` payloads from sneaking through and is the single source of truth for the object-form contract (Q1/Q7 reconciled — see docs/internal/specs/phase-1-chat-model-and-errors.md).
type FallbackModel struct {
	// Model Model slug for this fallback. May be a bare slug ("claude-sonnet-4.6") when `provider` is set, or a "provider/model" string when the slug routes through a passthrough provider.
	Model string `json:"model"`

	// Provider Routing key (e.g. "openrouter", "anthropic", "openai"). When set, the fallback uses this provider's API credentials — independent of the agent's primary model's provider. This is the FR-007 contract: a rate-limited primary does NOT poison the fallback's provider.
	Provider *string `json:"provider,omitempty"`
}

// GatewayRestartResponse Acknowledgement returned by POST /api/v1/gateway/restart. The gateway accepts the request, replies immediately, then drains in-flight work and re-execs the process (or exits cleanly for a supervisor). The SPA uses this response to start polling /health (and the WS reconnect path) to detect the gateway going down and coming back up.
type GatewayRestartResponse struct {
	// DrainSeconds Approximate number of seconds the gateway will wait for in-flight work to drain before re-execing. The SPA can use this as a lower bound before it starts polling /health for the gateway to come back.
	DrainSeconds int `json:"drain_seconds"`

	// Message Human-readable description of the scheduled restart.
	Message *string `json:"message,omitempty"`

	// RestartId Opaque identifier for this restart attempt. The SPA may echo it in logs to correlate the down→up transition; it is not required to poll.
	RestartId string `json:"restart_id"`

	// Status Always "restarting" — the request was accepted and a graceful restart has been scheduled. The HTTP response is sent BEFORE the process re-execs.
	Status GatewayRestartResponseStatus `json:"status"`
}

// GatewayRestartResponseStatus Always "restarting" — the request was accepted and a graceful restart has been scheduled. The HTTP response is sent BEFORE the process re-execs.
type GatewayRestartResponseStatus string

// GatewayStatus Gateway runtime status as returned by GET /status (polled by the frontend StatusBar every 15 seconds). Summarises the number of configured agents and channels plus a daily cost accumulator.
type GatewayStatus struct {
	// AgentCount Total number of configured agents (core + custom), including the implicit system agent.
	AgentCount int `json:"agent_count"`

	// ChannelCount Number of enabled channels including the always-available webchat channel.
	ChannelCount int `json:"channel_count"`

	// DailyCost Aggregate USD cost accrued today across all agents. Zero when cost tracking is disabled.
	DailyCost float64 `json:"daily_cost"`

	// Online Always true when the gateway is reachable and the agent loop is running.
	Online bool `json:"online"`

	// Version Gateway binary version string (e.g. "0.1.0" or the git short-sha for dev builds).
	Version *string `json:"version,omitempty"`
}

// GlobalToolPolicies Global tool policy configuration returned by GET /api/v1/security/tool-policies and accepted by PUT /api/v1/security/tool-policies.
type GlobalToolPolicies struct {
	// Policies Complete per-tool policy map. Every static builtin tool name (the full catalog: general + browser + system.*-legacy-named sysagent tools) MUST be present as an explicit, literal key with an "allow"/"ask"/"deny" value — this is not a sparse override set with a fallback default. There is no default_policy field; coverage is enforced by hard validation at boot and at every write, never a silent runtime default. Never null — always the full map.
	Policies map[string]GlobalToolPoliciesPolicies `json:"policies"`
}

// GlobalToolPoliciesPolicies defines model for GlobalToolPolicies.Policies.
type GlobalToolPoliciesPolicies string

// GodModeStatus O14 god-mode runtime state, returned by GET /api/v1/gateway/god-mode. God mode is the single global "bypass-permissions" switch: when enabled every agent's tool policy is floored at "allow" (no prompts), the kernel sandbox is off, network egress is open, and the shell guard is off — regardless of per-agent profiles. Audit logging, the prompt-injection guard, and rate limiting are never disabled. The per-agent overrides are non-destructive: switching god mode off restores prior behavior exactly.
type GodModeStatus struct {
	// Available Whether god mode is ACTIVE-CAPABLE in this boot: the build supports it (`supported` is true) AND authorization was granted before this process started, either via the legacy --allow-god-mode boot flag or via sandbox.god_mode_allowed persisted config (set by a prior UI enable + restart). Authorization is evaluated once at boot, so granting it via the UI (POST enabled=true while available=false) does not flip this to true until the gateway restarts — see GodModeUpdateResponse.restart_required.
	Available bool `json:"available"`

	// Enabled Current runtime god-mode state — whether the override is ACTIVE in this process right now. Always false when `available` is false (the switch is a no-op without availability). Can differ from the last value POSTed to this endpoint immediately after an enable that returned restart_required=true in GodModeUpdateResponse: the config write succeeded, but availability is boot-frozen, so the override does not become active until the gateway restarts.
	Enabled bool `json:"enabled"`

	// Persisted The raw persisted config intent — sandbox.god_mode as currently held in config, read directly and NOT gated by `available`. This is what lets a client distinguish "never armed" (persisted=false, available=false) from "armed via the UI, pending restart" (persisted=true, available=false): `enabled` collapses both of those to false, so it alone cannot tell them apart. Once `available` is also true, `persisted` and `enabled` agree (the override is both authorized-intended and live). A UI control that lets the operator arm/disarm god mode should bind its visual on/off state to `persisted`, not `enabled` — otherwise a pending-restart arm renders as if the switch were off, and clicking it again re-arms instead of disarming.
	Persisted bool `json:"persisted"`

	// Supported Whether this build supports god mode AT ALL — false only when compiled with the nogodmode build tag. Independent of runtime authorization: POST .../god-mode with enabled=true is permitted whenever `supported` is true, even if `available` is currently false (enabling then persists authorization to config and requires a gateway restart to actually take effect). When `supported` is false, enabling always returns 403 regardless of any authorization source.
	Supported bool `json:"supported"`
}

// GodModeUpdateRequest Body for POST /api/v1/gateway/god-mode. Flips the global god-mode ("bypass-permissions") switch. This is a high-blast-radius security change and requires a valid single-use re-auth consent token (password step-up) replayed in the X-Reauth-Token header — call POST /api/v1/auth/reauth first. Returns 403 when god mode is not SUPPORTED in this build (compiled with the nogodmode tag) and enabled=true. Enabling is otherwise always permitted: when the build supports it but this boot was not already authorized (see GodModeStatus.available), enabling persists authorization (sandbox.god_mode_allowed) and the runtime switch (sandbox.god_mode) to config in the same write, and the response's restart_required flag signals that the gateway must restart before the override actually takes effect. Disabling is always permitted regardless of availability (fail-safe: an operator can always reach the more-restrictive state).
type GodModeUpdateRequest struct {
	// Enabled Desired god-mode state. true turns god mode on, false turns it off.
	Enabled bool `json:"enabled"`
}

// GodModeUpdateResponse Response body for POST /api/v1/gateway/god-mode. Distinct from GodModeStatus because a successful enable can be persisted-but-not-yet- active: authorization (sandbox.god_mode_allowed) and the runtime switch (sandbox.god_mode) are both written to config, but the process's god-mode AVAILABILITY is decided once at boot — so enabling from a boot where god mode was not yet available takes effect only after a gateway restart. restart_required signals exactly that case. Disabling always applies live; restart_required is always false for a disable request.
type GodModeUpdateResponse struct {
	// Enabled The runtime god-mode state as just persisted by this call (echoes the request's `enabled`). This can be true even though the override is NOT yet active in this process when restart_required is also true — call GET /api/v1/gateway/god-mode after the restart to confirm activation.
	Enabled bool `json:"enabled"`

	// RestartRequired True when this call enabled god mode in a boot where it was not already available (the toggle changed config authorization, not live enforcement). The gateway must be restarted for the kernel-sandbox / tool-policy override to actually take effect. Always false for a disable request, and always false for an enable when god mode was already available in this boot (the override then applies live, matching the previous no-restart behavior).
	RestartRequired bool `json:"restart_required"`
}

// HealthResponse Response from GET /health. Returns HTTP 200 when the gateway is up. No authentication required.
type HealthResponse struct {
	// Status Always "ok" when the gateway is healthy.
	Status HealthResponseStatus `json:"status"`
}

// HealthResponseStatus Always "ok" when the gateway is healthy.
type HealthResponseStatus string

// IntegrationProvider A single configurable non-LLM integration provider as surfaced in Settings → Integrations (FR-12.1). Covers web-search providers (SearchProvider) and voice-input transcription providers (Transcriber). API keys are stored encrypted in credentials.json (via api_key_ref) — never returned in plaintext; configured is true when a key (or, for keyless providers like DuckDuckGo, the provider itself) is available.
type IntegrationProvider struct {
	// Active True when this provider is the one currently selected for its kind (the active search engine or the active transcriber).
	Active *bool `json:"active,omitempty"`

	// Configured True when this provider is usable — an API key is present (or, for keyless providers such as DuckDuckGo, always true).
	Configured bool `json:"configured"`

	// DisplayName Human-readable provider name for UI presentation.
	DisplayName string `json:"display_name"`

	// Id Provider identifier (e.g. "brave", "tavily", "duckduckgo", "elevenlabs").
	Id string `json:"id"`

	// Kind Whether this provider supplies web search or voice-input transcription.
	Kind IntegrationProviderKind `json:"kind"`

	// RequiresKey Whether this provider needs an API key to function.
	RequiresKey bool `json:"requires_key"`
}

// IntegrationProviderKind Whether this provider supplies web search or voice-input transcription.
type IntegrationProviderKind string

// IntegrationProviderUpdateRequest Body for PUT /api/v1/integrations/providers/{id}. Configures a search or voice-input integration provider (FR-12.1). Setting an api_key stores it encrypted (AES-256-GCM) in credentials.json and writes only the credential reference to config.json. Setting active=true selects this provider as the active one for its kind. Because integration edits are sensitive, the SPA must first obtain a re-auth token (POST /auth/reauth) and replay it in the X-Reauth-Token header — requests without a valid token are rejected 403.
type IntegrationProviderUpdateRequest struct {
	// Active When true, select this provider as the active one for its kind.
	Active *bool `json:"active,omitempty"`

	// ApiKey API key for the provider. Stored encrypted; omit to leave the current key unchanged. Required when first configuring a key-requiring provider.
	ApiKey *string `json:"api_key,omitempty"`

	// Kind Whether this provider is a search engine or a voice transcriber.
	Kind IntegrationProviderUpdateRequestKind `json:"kind"`
}

// IntegrationProviderUpdateRequestKind Whether this provider is a search engine or a voice transcriber.
type IntegrationProviderUpdateRequestKind string

// IntegrationProvidersResponse Response from GET /api/v1/integrations/providers. Lists every configurable search and voice-input integration provider (FR-12.1), plus which provider is currently active for each kind. Defined inline so the search/voice arrays reference the shared IntegrationProvider component (a relative file $ref would inline as anonymous structs).
type IntegrationProvidersResponse struct {
	// ActiveSearch id of the currently active search provider, when one is selected.
	ActiveSearch *string `json:"active_search,omitempty"`

	// ActiveVoice id of the currently active voice transcriber, when one is configured.
	ActiveVoice *string `json:"active_voice,omitempty"`

	// Search Configurable web-search providers.
	Search []IntegrationProvider `json:"search"`

	// Voice Configurable voice-input transcription providers.
	Voice []IntegrationProvider `json:"voice"`
}

// LibraryContentRequest Request body for PUT /api/v1/library/{workspace_id}/content. Writes text content to a file at the given workspace-relative path (library-spec.md D-5 editing scope), creating the file if it does not already exist and overwriting any existing content entirely. The path's parent directory must already exist within the workspace's work tree.
type LibraryContentRequest struct {
	// Content Full replacement text content for the file, UTF-8. Maximum 10485760 bytes (10 MB) — matches the threshold GET .../content uses to set too_large=true, so a file this endpoint can write is always one the read endpoint can subsequently render inline.
	Content string `json:"content"`

	// Path Workspace-relative path of the file to write, forward-slash separated. Never absolute and never containing a ".." segment (library-spec.md Constraints).
	Path string `json:"path"`
}

// LibraryContentResponse Response from GET /api/v1/library/{workspace_id}/content — the text content of one file for the SPA editor/viewer (library-spec.md D-5). Carries explicit is_text / too_large flags so the SPA can fall back to the download endpoint rather than guessing from the content field.
type LibraryContentResponse struct {
	// Content File text content, UTF-8. Present only when is_text is true and too_large is false; absent otherwise. The SPA MUST check both flags before rendering this field rather than treating an absent/empty value as "the file is empty."
	Content *string `json:"content,omitempty"`

	// IsText Whether the server sniffed this file as text (not binary). False for images, video, and other binary formats — the SPA renders a metadata card + download link instead (library-spec.md section 4 scope table).
	IsText bool `json:"is_text"`

	// Mime Best-effort MIME type sniffed from the file extension/content.
	Mime *string `json:"mime,omitempty"`

	// Path Workspace-relative path echoed back from the request.
	Path string `json:"path"`

	// Size Actual file size in bytes, provided even when content is omitted.
	Size int64 `json:"size"`

	// TooLarge Whether the file exceeds the server's inline-text-editing size threshold — the same 10485760-byte (10 MB) threshold enforced as LibraryContentRequest.content's maxLength, so a file this endpoint reports as editable is always one the write endpoint can accept back. When true, content is omitted even for a text file.
	TooLarge bool `json:"too_large"`
}

// LibraryEntry One file-explorer entry inside a workspace's work tree (library-spec.md D-2: "the Library is a file explorer over workspace trees, not a blob list" — entries are workspace-relative PATHS, not UUIDs, distinct from MediaLibraryEntry which is UUID-keyed). Returned by GET /api/v1/library/{workspace_id}/entries (directory listing), and echoed back by the write/rename/upload operations that produce or mutate a single entry.
type LibraryEntry struct {
	// IsDir True when this entry is a directory.
	IsDir bool `json:"is_dir"`

	// IsHidden True when this entry's name begins with a dot (".") — the sole, explicit definition of "hidden" for the Library, so client and server cannot drift on it. Excluded from GET .../entries by default (see that operation's include_hidden parameter); the reserved work-tree directory where uploads land, work/.library/, is the prototypical hidden entry. Included and set true here so the SPA can still style a hidden entry distinctly when the caller explicitly asks to see it.
	IsHidden bool `json:"is_hidden"`

	// IsTextEditable Whether the SPA should offer this entry for CodeMirror text editing (library-spec.md D-5 / section 4 scope table). Always false for directories. This is a best-effort hint from the directory listing, not a guarantee — GET .../content's is_text/too_large fields are the authoritative check at read time.
	IsTextEditable bool `json:"is_text_editable"`

	// Mime Best-effort MIME type sniffed from the file extension/content. Absent for directories and for files where sniffing was inconclusive.
	Mime *string `json:"mime,omitempty"`

	// ModifiedAt RFC3339 UTC last-modified timestamp of the underlying file or directory.
	ModifiedAt time.Time `json:"modified_at"`

	// Name Base filename or directory name (final path segment).
	Name string `json:"name"`

	// Path Workspace-relative path from the work-tree root (workspaces/<id>/work/, the root the Library explorer shows in full — not merely the reserved work/.library/ upload directory), forward-slash separated. Never absolute and never containing a ".." segment — every Library path operation resolves inside the target workspace's work tree, with symlinks not followed out of the root (library-spec.md Constraints).
	Path string `json:"path"`

	// Size File size in bytes. Always 0 for directories.
	Size int64 `json:"size"`
}

// LibraryRenameRequest Request body for POST /api/v1/library/{workspace_id}/rename. Renames or moves a file or directory within the workspace's work tree — "to" may name a different parent directory than "from", so this operation doubles as a move.
type LibraryRenameRequest struct {
	// From Current workspace-relative path of the file or directory, forward-slash separated. Never absolute and never containing a ".." segment (library-spec.md Constraints).
	From string `json:"from"`

	// To New workspace-relative path, same constraints as "from". Rejected (409) if an entry already exists at this path.
	To string `json:"to"`
}

// LibraryTransferRequest Request body shared by POST /api/v1/library/move and POST /api/v1/library/copy. Deliberately NOT scoped under {workspace_id} like the other Library operations — source and destination MAY be different workspaces, so both workspace ids are modelled explicitly here rather than one in the path and one in the body, making the two-workspace-capable shape obvious from the schema alone. A same-workspace move/copy is simply the case where from_workspace_id equals to_workspace_id (this is also what POST /api/v1/library/{workspace_id}/rename does under the hood — kept as same-workspace sugar over /move, see its own description).
// Cross-workspace transfer is a USER-facing capability only: reachable exclusively from the authenticated UI/CLI caller's own request, never invoked by an agent tool — agents remain confined to their own workspace's work tree. This is enforced server-side; it is stated here so no future caller wires an agent-facing tool to this operation.
type LibraryTransferRequest struct {
	// FromPath Workspace-relative path of the file or directory within from_workspace_id's work tree (workspaces/<from_workspace_id>/work/), forward-slash separated. Never absolute and never containing a ".." segment.
	FromPath string `json:"from_path"`

	// FromWorkspaceId Workspace ID that currently owns the file or directory.
	FromWorkspaceId string `json:"from_workspace_id"`

	// ToPath Destination workspace-relative path within to_workspace_id's work tree, same constraints as from_path. Rejected (409) if an entry already exists at this path.
	ToPath string `json:"to_path"`

	// ToWorkspaceId Destination workspace ID. Equal to from_workspace_id for a same-workspace move/copy.
	ToWorkspaceId string `json:"to_workspace_id"`
}

// LibraryUploadResponse Response from POST /api/v1/library/{workspace_id}/upload (HTTP 201). Returns the work-tree entries created by the upload — mirrors UploadFilesResponse's shape for the session-scoped uploader, but with LibraryEntry (path-keyed) items rather than UploadedFile.
type LibraryUploadResponse struct {
	// Entries Entries created by this upload, in the order the multipart parts were received.
	Entries []struct {
		// IsDir True when this entry is a directory.
		IsDir bool `json:"is_dir"`

		// IsHidden True when this entry's name begins with a dot (".") — the sole, explicit definition of "hidden" for the Library, so client and server cannot drift on it. Excluded from GET .../entries by default (see that operation's include_hidden parameter); the reserved work-tree directory where uploads land, work/.library/, is the prototypical hidden entry. Included and set true here so the SPA can still style a hidden entry distinctly when the caller explicitly asks to see it.
		IsHidden bool `json:"is_hidden"`

		// IsTextEditable Whether the SPA should offer this entry for CodeMirror text editing (library-spec.md D-5 / section 4 scope table). Always false for directories. This is a best-effort hint from the directory listing, not a guarantee — GET .../content's is_text/too_large fields are the authoritative check at read time.
		IsTextEditable bool `json:"is_text_editable"`

		// Mime Best-effort MIME type sniffed from the file extension/content. Absent for directories and for files where sniffing was inconclusive.
		Mime *string `json:"mime,omitempty"`

		// ModifiedAt RFC3339 UTC last-modified timestamp of the underlying file or directory.
		ModifiedAt time.Time `json:"modified_at"`

		// Name Base filename or directory name (final path segment).
		Name string `json:"name"`

		// Path Workspace-relative path from the work-tree root (workspaces/<id>/work/, the root the Library explorer shows in full — not merely the reserved work/.library/ upload directory), forward-slash separated. Never absolute and never containing a ".." segment — every Library path operation resolves inside the target workspace's work tree, with symlinks not followed out of the root (library-spec.md Constraints).
		Path string `json:"path"`

		// Size File size in bytes. Always 0 for directories.
		Size int64 `json:"size"`
	} `json:"entries"`
}

// LibraryWorkspaceNode One workspace as a node in the Library's virtual root listing (GET /api/v1/library/workspaces) — the sidebar entry point (library-spec.md D-3: "two entry points, one component"). Drilling into a node scopes all subsequent Library operations to that workspace's work tree via {workspace_id}.
type LibraryWorkspaceNode struct {
	// EntryCount Number of direct entries (files and directories) at the root of this workspace's work tree (workspaces/<id>/work/ — the same root GET .../entries lists), counted non-recursively so this stays cheap across every workspace on one request. Counts only non-hidden entries (see LibraryEntry.is_hidden), matching what the default (include_hidden=false) directory listing shows — the reserved work/.library/ upload directory is excluded from this count even though it exists. 0 when the work tree does not exist yet or has no visible entries.
	EntryCount int32 `json:"entry_count"`

	// Id Workspace identifier (matches Workspace.id).
	Id string `json:"id"`

	// Name Human-readable workspace name (matches Workspace.name).
	Name string `json:"name"`
}

// LoginRequest Credentials for authenticating an existing user.
type LoginRequest struct {
	// Password The user's password. Maximum 72 characters (bcrypt limit).
	Password string `json:"password"`

	// Username The user's login name.
	Username string `json:"username"`
}

// LoginResponse Returned on successful login or onboarding/complete. Contains the bearer token to use in subsequent Authorization headers and the username.
type LoginResponse struct {
	// Token Canonical opaque bearer token format used by Omnipus. Two forms are accepted: the current id-tagged form "omnipus_" + 8 hex (token id) + "_" + 64 hex (32 random bytes) = 81 characters, and the legacy form "omnipus_" + 64 hex = 72 characters (still honored for tokens minted before the multi-token model). The id segment routes verification to the right hash in the user's token set; only the 64-hex secret is bcrypt-hashed (kept under bcrypt's 72-byte limit). Used in Authorization headers, WS AuthFrame, and rotate-token responses.
	Token string `json:"token"`

	// Username The authenticated user's login name.
	Username string `json:"username"`

	// Warning Non-fatal advisory message. Present on onboarding/complete when the credential store is locked and the API key was stored in plaintext.
	Warning *string `json:"warning,omitempty"`
}

